package dev.falix.studiomobile;
import android.content.*;import android.net.Uri;import android.os.Environment;import android.provider.DocumentsContract;import android.database.Cursor;
import org.json.*;import org.yaml.snakeyaml.*;import org.yaml.snakeyaml.constructor.SafeConstructor;
import java.io.*;import java.util.*;import java.util.zip.*;import java.security.MessageDigest;
/** Filesystem/SAF repository. One portable YAML manifest per experience; never stores credentials. */
final class ManagedProjects {
 static final class Record {Uri folder;JSONObject data;String name(){return data.optString("name");}JSONArray places(){return data.optJSONArray("places");}}
 final Context c;final ProjectStore store;final SharedPreferences prefs;final ArrayList<String> warnings=new ArrayList<>();
 ManagedProjects(Context c,ProjectStore s){this.c=c;store=s;prefs=c.getSharedPreferences("settings",0);}
 boolean file(Uri u){return "file".equals(u.getScheme());}
 Uri child(Uri dir,String name)throws Exception{if(file(dir)){File f=new File(dir.getPath(),name);return f.exists()?Uri.fromFile(f):null;}String id=DocumentsContract.getDocumentId(dir);try(Cursor q=c.getContentResolver().query(DocumentsContract.buildChildDocumentsUriUsingTree(dir,id),new String[]{"document_id","_display_name"},null,null,null)){if(q!=null)while(q.moveToNext())if(name.equals(q.getString(1)))return DocumentsContract.buildDocumentUriUsingTree(dir,q.getString(0));}return null;}
 Uri make(Uri parent,String name,boolean folder)throws Exception{if(child(parent,name)!=null)throw new IOException("A file with that name already exists.");if(file(parent)){File f=new File(parent.getPath(),name);if(folder?!f.mkdir():!f.createNewFile())throw new IOException("Could not create "+name);return Uri.fromFile(f);}Uri u=DocumentsContract.createDocument(c.getContentResolver(),parent,folder?DocumentsContract.Document.MIME_TYPE_DIR:"application/octet-stream",name);if(u==null)throw new IOException("The folder provider could not create "+name);return u;}
 Uri root()throws Exception{if(!store.available())throw new IOException("Choose project storage first.");if(store.tree()!=null){Uri dir=DocumentsContract.buildDocumentUriUsingTree(store.tree(),DocumentsContract.getTreeDocumentId(store.tree()));Uri projects=child(dir,"Projects");return projects!=null?projects:make(dir,"Projects",true);}File f=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOCUMENTS),"StudioMobile/Projects");if(!f.exists()&&!f.mkdirs())throw new IOException("Cannot create the project directory.");return Uri.fromFile(f);}
 InputStream input(Uri u)throws Exception{if(u==null)throw new IOException("Project file is missing.");return file(u)?new FileInputStream(u.getPath()):c.getContentResolver().openInputStream(u);}
 OutputStream output(Uri u)throws Exception{return file(u)?new FileOutputStream(u.getPath()):c.getContentResolver().openOutputStream(u,"wt");}
 byte[] bytes(Uri u,long max)throws Exception{try(InputStream in=input(u)){if(in==null)throw new IOException("Cannot read project file.");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[32768];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>max)throw new IOException("File exceeds safety limit.");out.write(b,0,n);}return out.toByteArray();}}
 void write(Uri u,byte[] b)throws Exception{if(file(u)){File dest=new File(u.getPath()),tmp=new File(dest.getPath()+".tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(b);out.getFD().sync();}if(!tmp.renameTo(dest)){tmp.delete();throw new IOException("Could not commit file.");}}else try(OutputStream out=output(u)){if(out==null)throw new IOException("Cannot write project file.");out.write(b);}}
 void deleteUri(Uri u)throws Exception{if(file(u)){File f=new File(u.getPath());if(f.isDirectory()&&!java.nio.file.Files.isSymbolicLink(f.toPath())){File[] a=f.listFiles();if(a!=null)for(File x:a)deleteUri(Uri.fromFile(x));}if(f.exists()&&!f.delete())throw new IOException("Cannot remove "+f.getName());}else if(!DocumentsContract.deleteDocument(c.getContentResolver(),u))throw new IOException("Provider refused deletion.");}
 static Object plain(Object o)throws Exception{if(o instanceof JSONObject){Map<String,Object> map=new LinkedHashMap<>();Iterator<String> it=((JSONObject)o).keys();while(it.hasNext()){String k=it.next();map.put(k,plain(((JSONObject)o).opt(k)));}return map;}if(o instanceof JSONArray){List<Object> a=new ArrayList<>();for(int i=0;i<((JSONArray)o).length();i++)a.add(plain(((JSONArray)o).get(i)));return a;}return o==JSONObject.NULL?null:o;}
 static String yaml(JSONObject o)throws Exception{DumperOptions d=new DumperOptions();d.setDefaultFlowStyle(DumperOptions.FlowStyle.BLOCK);d.setPrettyFlow(true);d.setIndent(2);return new Yaml(d).dump(plain(o));}
 static JSONObject parse(byte[] b)throws Exception{LoaderOptions options=new LoaderOptions();options.setAllowDuplicateKeys(false);options.setMaxAliasesForCollections(0);options.setNestingDepthLimit(16);options.setCodePointLimit(1024*1024);Object m=new Yaml(new SafeConstructor(options)).load(new String(b,"UTF-8"));if(!(m instanceof Map))throw new IOException("Invalid project manifest.");return new JSONObject((Map)m);}
 Record load(Uri folder)throws Exception{Record r=new Record();r.folder=folder;r.data=parse(bytes(child(folder,"project.yml"),1024*1024));if(r.data.optInt("schema")!=1||!r.data.optString("id").matches("[a-f0-9-]{36}")||r.places()==null||r.places().length()==0||r.places().length()>100)throw new IOException("Unsupported project manifest.");boolean hasStart=false;Set<String> seen=new HashSet<>();for(int i=0;i<r.places().length();i++){JSONObject p=r.places().getJSONObject(i);if(!seen.add(p.optString("id")))throw new IOException("Duplicate place ID.");if(p.optString("id").equals(r.data.optString("start_place")))hasStart=true;if(!p.optString("file").matches("places/[a-f0-9-]{36}\\.rbxlx?"))throw new IOException("Unsafe place path.");}if(!hasStart)throw new IOException("Missing start place.");return r;}
 void save(Record r)throws Exception{r.data.put("updated",System.currentTimeMillis());Uri target=child(r.folder,"project.yml");byte[] old=target==null?null:bytes(target,1024*1024);if(target==null)target=make(r.folder,"project.yml",false);if(old!=null){Uri backup=child(r.folder,"project.yml.bak");if(backup==null)backup=make(r.folder,"project.yml.bak",false);write(backup,old);}try{write(target,yaml(r.data).getBytes("UTF-8"));load(r.folder);}catch(Exception e){if(old!=null)write(target,old);throw e;}}
 ArrayList<Record> list()throws Exception{warnings.clear();ArrayList<Record> result=new ArrayList<>();Uri root=root();if(file(root)){File[] dirs=new File(root.getPath()).listFiles();if(dirs!=null)for(File d:dirs)if(d.isDirectory()&&!java.nio.file.Files.isSymbolicLink(d.toPath())&&new File(d,"project.yml").exists())try{result.add(load(Uri.fromFile(d)));}catch(Exception e){warnings.add("Could not read "+d.getName()+": "+RobloxApi.safe(e));}}else{try(Cursor q=c.getContentResolver().query(DocumentsContract.buildChildDocumentsUriUsingTree(root,DocumentsContract.getDocumentId(root)),new String[]{"document_id","_display_name","mime_type"},null,null,null)){if(q!=null)while(q.moveToNext())if(DocumentsContract.Document.MIME_TYPE_DIR.equals(q.getString(2)))try{Uri dir=DocumentsContract.buildDocumentUriUsingTree(root,q.getString(0));if(child(dir,"project.yml")!=null)result.add(load(dir));}catch(Exception e){warnings.add("Could not read "+q.getString(1));}}}result.sort((a,b)->Long.compare(b.data.optLong("updated"),a.data.optLong("updated")));return result;}
 Record create(String name,String description,List<String> devices,String template,String startName,int players,double gravity,boolean streaming,RobloxApi.Session s)throws Exception{validate(name,devices,players,gravity);String id=UUID.randomUUID().toString();Uri dir=make(root(),slug(name)+"-"+id.substring(0,8),true);try{make(dir,"places",true);make(dir,"backups",true);Record r=new Record();r.folder=dir;r.data=new JSONObject().put("schema",1).put("id",id).put("name",name.trim()).put("description",description).put("created",System.currentTimeMillis()).put("creator",new JSONObject().put("type","User").put("user_id",s==null?JSONObject.NULL:s.userId).put("username",s==null?JSONObject.NULL:s.username)).put("devices",new JSONArray(devices)).put("cloud",new JSONObject().put("universe_id",JSONObject.NULL)).put("places",new JSONArray());JSONObject p=addPlaceData(r,startName,template,players,gravity,streaming);r.data.put("start_place",p.getString("id"));save(r);return r;}catch(Exception e){try{deleteUri(dir);}catch(Exception ignored){}throw e;}}
 static void validate(String name,List<String> devices,int players,double gravity)throws Exception{if(name.trim().isEmpty()||name.length()>100)throw new IOException("Enter a name of 1–100 characters.");if(devices.isEmpty())throw new IOException("Select at least one device.");if(players<1||players>100)throw new IOException("Server size must be between 1 and 100.");if(Double.isNaN(gravity)||Double.isInfinite(gravity)||gravity<0||gravity>10000)throw new IOException("Gravity must be between 0 and 10000.");}
 static String slug(String name){String s=name.replaceAll("[^\\p{L}\\p{N} _.-]","_").trim();if(s.isEmpty())s="Project";return s.substring(0,Math.min(45,s.length()));}
 JSONObject addPlaceData(Record r,String name,String template,int players,double gravity,boolean streaming)throws Exception{if(name.trim().isEmpty()||name.length()>100)throw new IOException("Enter a place name.");if(r.places().length()>=100)throw new IOException("Project limit: 100 places.");String id=UUID.randomUUID().toString();String file=id+".rbxlx";Uri u=make(child(r.folder,"places"),file,false);byte[] bytes=PlaceTemplate.generate(name,template,gravity,streaming).getBytes("UTF-8");write(u,bytes);JSONObject p=new JSONObject().put("id",id).put("name",name.trim()).put("file","places/"+file).put("template",template).put("server_size",players).put("gravity",gravity).put("streaming",streaming).put("cloud_place_id",JSONObject.NULL).put("sha256",hash(bytes)).put("last_upload",JSONObject.NULL);r.places().put(p);return p;}
 void addPlace(Record r,String name,String template)throws Exception{JSONObject snapshot=new JSONObject(r.data.toString());JSONObject p=null;try{p=addPlaceData(r,name,template,50,196.2,false);save(r);}catch(Exception e){if(p!=null)try{deleteUri(placeUri(r,p));}catch(Exception ignored){}r.data=snapshot;throw e;}}
 Uri placeUri(Record r,JSONObject p)throws Exception{return child(child(r.folder,"places"),p.getString("file").substring(7));}
 static String hash(byte[] b)throws Exception{StringBuilder out=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(b))out.append(String.format(Locale.US,"%02x",x&255));return out.toString();}
 static long transfer(InputStream in,OutputStream out,long max)throws Exception{byte[] buffer=new byte[32768];long total=0;int n;while((n=in.read(buffer))!=-1){total+=n;if(total>max)throw new IOException("File exceeds safety limit.");out.write(buffer,0,n);}return total;}
 static String hashFile(File f)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}StringBuilder hex=new StringBuilder();for(byte x:d.digest())hex.append(String.format(Locale.US,"%02x",x&255));return hex.toString();}
 void writeFrom(Uri destination,InputStream in)throws Exception{if(file(destination)){File outFile=new File(destination.getPath()),tmp=new File(outFile.getPath()+".tmp");try{try(FileOutputStream out=new FileOutputStream(tmp)){transfer(in,out,RobloxApi.MAX_DOWNLOAD);out.getFD().sync();}if(!tmp.renameTo(outFile))throw new IOException("Could not commit place file.");}catch(Exception e){tmp.delete();throw e;}}else try(OutputStream out=output(destination)){if(out==null)throw new IOException("Cannot write place file.");transfer(in,out,RobloxApi.MAX_DOWNLOAD);}}
 File stage(Record r,JSONObject p)throws Exception{File tmp=File.createTempFile("publish-",".rbxlx",c.getCacheDir());try{try(InputStream in=input(placeUri(r,p));OutputStream out=new FileOutputStream(tmp)){if(in==null)throw new IOException("Missing place file.");transfer(in,out,RobloxApi.MAX_DOWNLOAD);}if(!RobloxApi.validPlace(tmp))throw new IOException("Invalid place file.");return tmp;}catch(Exception e){tmp.delete();throw e;}}
 void replace(Record r,JSONObject p,File source)throws Exception{if(source.length()>RobloxApi.MAX_DOWNLOAD||!RobloxApi.validPlace(source))throw new IOException("Invalid or oversized Roblox place file.");Uri old=placeUri(r,p);Uri backup=make(child(r.folder,"backups"),p.getString("id")+"-"+System.currentTimeMillis()+".bak",false);try(InputStream in=input(old)){writeFrom(backup,in);}String ext=RobloxApi.xmlPlace(source)?".rbxlx":".rbxl";String name=p.getString("id")+ext;Uri target=child(child(r.folder,"places"),name);if(target==null)target=make(child(r.folder,"places"),name,false);JSONObject snapshot=new JSONObject(r.data.toString());try{try(InputStream in=new FileInputStream(source)){writeFrom(target,in);}p.put("file","places/"+name).put("sha256",hashFile(source));save(r);if(!target.equals(old))deleteUri(old);}catch(Exception e){if(target.equals(old))try(InputStream in=input(backup)){writeFrom(old,in);}else try{deleteUri(target);}catch(Exception ignored){}r.data=snapshot;throw e;}}
 void removePlace(Record r,JSONObject p)throws Exception{if(r.places().length()==1)throw new IOException("Keep at least one place.");if(p.getString("id").equals(r.data.getString("start_place")))throw new IOException("Choose another local start place first.");Uri original=placeUri(r,p);Uri backup=make(child(r.folder,"backups"),p.getString("id")+"-removed-"+System.currentTimeMillis()+".bak",false);try(InputStream in=input(original)){writeFrom(backup,in);}for(int i=0;i<r.places().length();i++)if(r.places().getJSONObject(i).getString("id").equals(p.getString("id"))){r.places().remove(i);break;}save(r);deleteUri(original);}
 File export(Record r)throws Exception{File zip=File.createTempFile("project-",".zip",c.getCacheDir());try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(zip))){zipEntry(out,"project.yml",yaml(r.data).getBytes("UTF-8"));long total=0;for(int i=0;i<r.places().length();i++){JSONObject p=r.places().getJSONObject(i);out.putNextEntry(new ZipEntry(p.getString("file")));try(InputStream in=input(placeUri(r,p))){total+=transfer(in,out,RobloxApi.MAX_DOWNLOAD);}out.closeEntry();if(total>300L*1024*1024)throw new IOException("Snapshot exceeds 300 MiB.");}}catch(Exception e){zip.delete();throw e;}return zip;}
 void zipEntry(ZipOutputStream z,String name,byte[] bytes)throws Exception{z.putNextEntry(new ZipEntry(name));z.write(bytes);z.closeEntry();}
 Record importZip(File zipFile)throws Exception{try(ZipFile zip=new ZipFile(zipFile)){if(zip.size()>500)throw new IOException("ZIP has too many entries.");ZipEntry manifest=zip.getEntry("project.yml");if(manifest==null)throw new IOException("ZIP must contain project.yml at its root.");byte[] yamlBytes;try(InputStream in=zip.getInputStream(manifest)){yamlBytes=bounded(in,1024*1024);}JSONObject data=parse(yamlBytes);JSONArray places=data.optJSONArray("places");if(data.optInt("schema")!=1||places==null||places.length()<1||places.length()>100)throw new IOException("Unsupported project ZIP.");Set<String> accepted=new HashSet<>();accepted.add("project.yml");boolean hasStart=false;for(int i=0;i<places.length();i++){JSONObject p=places.getJSONObject(i);String file=p.optString("file");if(!file.matches("places/[a-f0-9-]{36}\\.rbxlx?")||!accepted.add(file)||zip.getEntry(file)==null)throw new IOException("Invalid place path or missing file.");if(p.optString("id").equals(data.optString("start_place")))hasStart=true;}if(!hasStart)throw new IOException("Missing start place.");Enumeration<? extends ZipEntry> entries=zip.entries();while(entries.hasMoreElements()){String name=entries.nextElement().getName();if(!accepted.contains(name)&&!name.matches("backups/[a-f0-9-]+\\.bak"))throw new IOException("Unexpected ZIP entry: "+name);}Uri dir=make(root(),slug(data.optString("name","Imported project"))+"-"+UUID.randomUUID().toString().substring(0,8),true);try{make(dir,"places",true);make(dir,"backups",true);Record r=new Record();r.folder=dir;r.data=data;r.data.put("id",UUID.randomUUID().toString()).put("cloud",new JSONObject().put("universe_id",JSONObject.NULL));long total=0;for(int i=0;i<places.length();i++){JSONObject p=places.getJSONObject(i);File test=File.createTempFile("validate-",".part",c.getCacheDir());try{try(InputStream in=zip.getInputStream(zip.getEntry(p.getString("file")));OutputStream out=new FileOutputStream(test)){total+=transfer(in,out,RobloxApi.MAX_DOWNLOAD);}if(total>300L*1024*1024)throw new IOException("Imported project exceeds 300 MiB.");if(!hashFile(test).equals(p.optString("sha256")))throw new IOException("Place checksum does not match the manifest.");if(!RobloxApi.validPlace(test))throw new IOException("Invalid place content.");try(InputStream in=new FileInputStream(test)){writeFrom(make(child(dir,"places"),p.getString("file").substring(7),false),in);}}finally{test.delete();}p.put("cloud_place_id",JSONObject.NULL).put("last_upload",JSONObject.NULL).remove("last_attempt");}save(r);return r;}catch(Exception e){try{deleteUri(dir);}catch(Exception ignored){}throw e;}}}
 static byte[] bounded(InputStream in,long max)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Decompressed entry exceeds safety limit.");out.write(b,0,n);}return out.toByteArray();}
 Record duplicate(Record r)throws Exception{Uri dir=make(root(),slug(r.name())+"-copy-"+UUID.randomUUID().toString().substring(0,8),true);try{make(dir,"places",true);make(dir,"backups",true);Record copy=new Record();copy.folder=dir;copy.data=new JSONObject(r.data.toString());copy.data.put("id",UUID.randomUUID().toString()).put("name",r.name()+" copy").put("created",System.currentTimeMillis()).put("cloud",new JSONObject().put("universe_id",JSONObject.NULL));for(int i=0;i<copy.places().length();i++){JSONObject p=copy.places().getJSONObject(i);p.put("cloud_place_id",JSONObject.NULL).put("last_upload",JSONObject.NULL);try(InputStream in=input(placeUri(r,r.places().getJSONObject(i)))){writeFrom(make(child(dir,"places"),p.getString("file").substring(7),false),in);}}save(copy);return copy;}catch(Exception e){try{deleteUri(dir);}catch(Exception ignored){}throw e;}}
}
